const lead = $input.first().json;
const s = $('Settings Loader').first().json;

const CONFIG = {
  COMPANY_NAME: s.business_name,
  APPOINTMENT_TERM: s.appointment_term,
  OWNER_PHONE: s.owner_phone_e164,
  OWNER_EMAIL: s.owner_email,
  TWILIO_FROM_NUMBER: s.twilio_from_number,
  EMAIL_ALERTS_ENABLED: s.email_alerts_enabled,
  SMS_ALERTS_ENABLED: s.sms_owner_alerts_enabled,
  DEFAULT_TIMEZONE: s.timezone,
  SHEET_URL: s.crm_sheet_url
};

const render = (tpl, vars) => tpl.replace(/\{\{(\w+)\}\}/g, (_, k) => (vars[k] !== undefined && vars[k] !== null) ? vars[k] : '');

const name = [lead.firstName, lead.lastName].filter(Boolean).join(' ') || 'Unknown';
const firstName = lead.firstName || 'there';
const phone = lead.phone || 'Not provided';
const email = lead.email || 'Not provided';
const service = lead.serviceNeeded || 'Not specified';
const address = lead.address || 'Not provided';
const notes = lead.description || lead.notes || '';
const source = lead.source || 'Unknown';
const leadId = lead.leadId || '';
const schedulingFailed = !!lead.schedulingFailed;
const confirmedDate = lead.confirmedDate || '';
const confirmedTime = lead.confirmedTime || '';

let apptDisplay = 'Not yet scheduled — needs manual scheduling';
if (!schedulingFailed && confirmedDate && confirmedTime) {
  try {
    const dm = String(confirmedDate).split('-').map(Number);
    const dt = DateTime.fromObject({ year: dm[0], month: dm[1], day: dm[2] }, { zone: CONFIG.DEFAULT_TIMEZONE });
    apptDisplay = dt.toFormat('cccc, LLLL d') + ' at ' + confirmedTime;
  } catch (e) { apptDisplay = confirmedDate + ' ' + confirmedTime; }
}

let submitted = 'Just now';
if (lead.dateCreated) {
  try {
    submitted = DateTime.fromISO(lead.dateCreated).setZone(CONFIG.DEFAULT_TIMEZONE).toFormat("MMM d, yyyy 'at' h:mm a ZZZZ");
  } catch (e) { submitted = lead.dateCreated; }
}

const smsMessage = schedulingFailed
  ? render(s.sms_template_lead_alert_failed, { name, service, appointmentTerm: CONFIG.APPOINTMENT_TERM, phone })
  : render(s.sms_template_lead_alert_success, { appointmentTerm: CONFIG.APPOINTMENT_TERM, name, service, apptDisplay, phone });

const emailSubject = CONFIG.COMPANY_NAME + ' - ' + (schedulingFailed ? 'ACTION NEEDED: ' : 'New ' + CONFIG.APPOINTMENT_TERM + ' booked: ') + name;

const rows = [
  ['Name', name],
  ['Phone', phone],
  ['Email', email],
  ['Address', address],
  ['Service Requested', service],
  [CONFIG.APPOINTMENT_TERM.charAt(0).toUpperCase() + CONFIG.APPOINTMENT_TERM.slice(1), apptDisplay],
  ['Notes', notes || 'None'],
  ['Lead Source', source],
  ['Submitted', submitted]
];
if (leadId) rows.push(['Lead ID', leadId]);

const rowsHtml = rows.map(([label, value]) =>
  '<tr><td style="padding:6px 12px 6px 0;font-weight:bold;color:#374151;white-space:nowrap;">' + label + '</td><td style="padding:6px 0;color:#111827;">' + value + '</td></tr>'
).join('');

const noteHtml = schedulingFailed
  ? '<p style="color:#b91c1c;font-weight:bold;">This lead could not be auto-scheduled. Please call them to set up their ' + CONFIG.APPOINTMENT_TERM + '.</p>'
  : '<p style="color:#6b7280;font-size:12px;margin-top:24px;">This ' + CONFIG.APPOINTMENT_TERM + ' was booked automatically. Reply to the text alert: <strong>1</strong> to keep it, <strong>2</strong> to reschedule, or <strong>3</strong> to cancel. No login or sheet access needed.</p>';

const emailHtml =
  '<div style="font-family:Arial,Helvetica,sans-serif;max-width:560px;margin:0 auto;color:#111827;">' +
  '<h2 style="color:#111827;border-bottom:2px solid #e5e7eb;padding-bottom:8px;">' + (schedulingFailed ? 'Lead Needs Manual Scheduling' : 'New ' + CONFIG.APPOINTMENT_TERM.charAt(0).toUpperCase() + CONFIG.APPOINTMENT_TERM.slice(1) + ' Booked') + '</h2>' +
  '<table style="width:100%;border-collapse:collapse;margin-top:12px;">' + rowsHtml + '</table>' +
  '<p style="margin-top:20px;">' +
  '<a href="tel:' + phone + '" style="background:#111827;color:#ffffff;padding:10px 18px;border-radius:6px;text-decoration:none;font-weight:bold;display:inline-block;">Call ' + firstName + '</a>' +
  '&nbsp;&nbsp;' +
  '<a href="' + CONFIG.SHEET_URL + '" style="background:#374151;color:#ffffff;padding:10px 18px;border-radius:6px;text-decoration:none;font-weight:bold;display:inline-block;">View in Sheet</a>' +
  '</p>' +
  noteHtml +
  '</div>';

return [{ json: {
  ...lead,
  emailEnabled: CONFIG.EMAIL_ALERTS_ENABLED,
  smsEnabled: CONFIG.SMS_ALERTS_ENABLED,
  ownerEmail: CONFIG.OWNER_EMAIL,
  ownerPhone: CONFIG.OWNER_PHONE,
  twilioFrom: CONFIG.TWILIO_FROM_NUMBER,
  emailSubject,
  emailHtml,
  smsMessage
}}];
